Ext.define('bcp.view.OrderWindow', {
    extend: 'Ext.window.Window',
    alias: 'widget.orderwindow',

    requires: [
        'Ext.form.Panel',
        'Ext.toolbar.Toolbar',
        'Ext.button.Button',
        'Ext.form.field.Date'
    ],

    modal: true,
    height: 313,
    width: 400,
    defaultFocus: 'noButton',
    layout: 'card',
    closable: false,
    defaultButton: 'noBtn',
    title: 'Update Order Information',
    defaultListenerScope: true,

    items: [
        {
            xtype: 'form',
            flex: 1,
            defaults: {labelWidth: 200},
            bodyPadding: 10,
            dockedItems: [
                {
                    xtype: 'toolbar',
                    dock: 'bottom',
                    defaultButtonUI: 'default',
                    layout: {type: 'hbox', pack: 'center'},
                    items: [
                        {
                            xtype: 'button',
                            reference: 'noBtn',
                            itemId: 'noButton',
                            width: 80,
                            text: 'Cancel',
                            listeners: {click: 'onNoButtonClick'}
                        },
                        {
                            xtype: 'button',
                            formBind: true,
                            width: 80,
                            text: 'Apply',
                            listeners: {click: 'onApplyButtonClick'}
                        }
                    ]
                }
            ],
            items: [
                {
                    xtype: 'datefield',
                    fieldLabel: 'Estimated Date of Arrival',
                    name: 'estimatedTimeOfArrival'
                },
                {
                    xtype: 'textfield',
                    anchor: '100%',
                    fieldLabel: 'Order Number',
                    name: 'orderNumber',
                    maxLength: 100
                },
                {
                    xtype: 'textfield',
                    anchor: '100%',
                    fieldLabel: 'GSA Session Number',
                    name: 'gsaSessionNumber',
                    maxLength: 200
                },
                {
                    xtype: 'textfield',
                    anchor: '100%',
                    fieldLabel: 'Purchase Order Number',
                    name: 'purchaseOrderNumber',
                    maxLength: 100
                }
            ]
        }
    ],

    onNoButtonClick: function (button, e, eOpts) {
        this.fireEvent('cancelUpdateOrder');
    },

    onApplyButtonClick: function (button, e, eOpts) {
        var form = this.query('form')[0];

        form.updateRecord();

        var rec = form.getRecord();

        //used rec.data instead of formData so the estimated time of arrvial will have the standard
        //javascript date format like 2018-03-10T00:00:00 and not the string format of "03/10/2018"
        this.fireEvent('applyUpdateOrder', rec.data);
    }
});
